-- SEG-03 (T10) — Bitácora append-only con hash encadenado por tenant.
-- RLS ENABLE + FORCE. El rol optisaas_audit_writer solo inserta y lee.
-- optisaas_app solo lee, según la matriz R19. UPDATE, DELETE y TRUNCATE
-- quedan revocados y un trigger los rechaza aunque el dueño insista.
-- No hay columna de contenido clínico. TODO(Q-07): sin plazo de conservación.
CREATE TABLE "auditoria" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "tenant_id" uuid NOT NULL REFERENCES "tenants"("id"),
  "ts" timestamptz DEFAULT now() NOT NULL,
  "actor_id" uuid REFERENCES "usuarios"("id"),
  "rol" text,
  "sede_id" uuid REFERENCES "sedes"("id"),
  "recurso" text NOT NULL,
  "recurso_id" text,
  "accion" text NOT NULL,
  "resultado" text NOT NULL,
  "ip" text,
  "agente" text,
  "request_id" text,
  "hash_previo" bytea,
  "hash" bytea NOT NULL,
  CONSTRAINT "auditoria_accion_valida" CHECK ("accion" in (
    'lectura','crear','leer','actualizar','firmar','anular','exportar','solicitar',
    'autenticacion','cambiar_sede','adenda','impresion','descarga','break_glass',
    'configuracion','retencion','cambio_rol'
  )),
  CONSTRAINT "auditoria_resultado_valido" CHECK ("resultado" in ('ok','denegado','error')),
  CONSTRAINT "auditoria_recurso_referencia" CHECK ("recurso" ~ '^[A-Za-z0-9_]{1,40}$'),
  CONSTRAINT "auditoria_rol_referencia" CHECK ("rol" IS NULL OR "rol" ~ '^[a-z_]{1,60}$')
);
--> statement-breakpoint
CREATE INDEX "auditoria_tenant_id_id_idx" ON "auditoria" ("tenant_id", "id");
--> statement-breakpoint
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'optisaas_audit_writer') THEN
    CREATE ROLE optisaas_audit_writer NOLOGIN;
  END IF;
END $$;
