CREATE POLICY auditoria_lectura_app ON auditoria FOR SELECT TO optisaas_app
  USING (
    tenant_id::text = current_setting('app.tenant_id', true)
    AND (
      (
        current_setting('app.rol', true) IN ('admin', 'auditor')
        AND (
          sede_id IS NULL
          OR sede_id::text = ANY (string_to_array(coalesce(current_setting('app.sedes', true), ''), ','))
        )
      )
      OR (
        current_setting('app.rol', true) IN ('optometra', 'oftalmologo', 'director_cientifico')
        AND actor_id::text = current_setting('app.usuario_id', true)
        AND sede_id::text = current_setting('app.sede_id', true)
      )
    )
  );
--> statement-breakpoint
CREATE POLICY auditoria_lectura_writer ON auditoria FOR SELECT TO optisaas_audit_writer
  USING (tenant_id::text = current_setting('app.tenant_id', true));
--> statement-breakpoint
CREATE POLICY auditoria_insercion_writer ON auditoria FOR INSERT TO optisaas_audit_writer
  WITH CHECK (tenant_id::text = current_setting('app.tenant_id', true));
