CREATE OR REPLACE FUNCTION auditoria_rechazar_cambio()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  RAISE EXCEPTION 'auditoria es append-only: % prohibido', TG_OP
    USING ERRCODE = '55000';
END;
$$;
--> statement-breakpoint
CREATE TRIGGER auditoria_append_only
  BEFORE UPDATE OR DELETE ON auditoria
  FOR EACH ROW EXECUTE FUNCTION auditoria_rechazar_cambio();
--> statement-breakpoint
CREATE TRIGGER auditoria_append_only_truncate
  BEFORE TRUNCATE ON auditoria
  FOR EACH STATEMENT EXECUTE FUNCTION auditoria_rechazar_cambio();
--> statement-breakpoint
CREATE OR REPLACE FUNCTION ultimo_hash_auditoria(p_tenant uuid)
RETURNS bytea
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  ultimo bytea;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(p_tenant::text, 0));
  SELECT a.hash INTO ultimo
    FROM auditoria a
   WHERE a.tenant_id = p_tenant
   ORDER BY a.id DESC
   LIMIT 1;
  RETURN ultimo;
END;
$$;
--> statement-breakpoint
CREATE OR REPLACE FUNCTION registrar_fila_auditoria(
  p_tenant uuid,
  p_ts timestamptz,
  p_actor uuid,
  p_rol text,
  p_sede uuid,
  p_recurso text,
  p_recurso_id text,
  p_accion text,
  p_resultado text,
  p_ip text,
  p_agente text,
  p_request_id text,
  p_hash_previo bytea,
  p_hash bytea
) RETURNS bigint
LANGUAGE plpgsql
SET search_path = public
AS $$
DECLARE
  ultimo bytea;
  nuevo bigint;
BEGIN
  IF current_user <> 'optisaas_audit_writer' THEN
    RAISE EXCEPTION 'la insercion de auditoria exige optisaas_audit_writer';
  END IF;
  IF p_hash IS NULL OR octet_length(p_hash) <> 32 THEN
    RAISE EXCEPTION 'hash de auditoria invalido';
  END IF;
  IF p_hash_previo IS NOT NULL AND octet_length(p_hash_previo) <> 32 THEN
    RAISE EXCEPTION 'hash previo de auditoria invalido';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_tenant::text, 0));
  SELECT a.hash INTO ultimo
    FROM auditoria a
   WHERE a.tenant_id = p_tenant
   ORDER BY a.id DESC
   LIMIT 1;
  IF ultimo IS DISTINCT FROM p_hash_previo THEN
    RAISE EXCEPTION 'cadena de auditoria desfasada';
  END IF;
  PERFORM set_config('app.tenant_id', p_tenant::text, true);
  INSERT INTO auditoria (
    tenant_id, ts, actor_id, rol, sede_id, recurso, recurso_id,
    accion, resultado, ip, agente, request_id, hash_previo, hash
  ) VALUES (
    p_tenant, p_ts, p_actor, p_rol, p_sede, p_recurso, p_recurso_id,
    p_accion, p_resultado, p_ip, p_agente, p_request_id, p_hash_previo, p_hash
  )
  RETURNING id INTO nuevo;
  RETURN nuevo;
END;
$$;
--> statement-breakpoint
